// Optional real-weight fixture generated by tools/dinov2_segmentation_smoke.py.
// Checks the same C ABI used by C# plus the public C++ segmentation loader.
#include "vision_inference.h"
#include "vision_runtime_c.h"
#include "model_crypto.h"
#include <filesystem>
#include <iostream>
#include <memory>
#include <stdexcept>

static void require(bool condition, const char* message) {
    if (!condition) throw std::runtime_error(message);
}

int main(int argc, char** argv) {
    try {
        require(argc == 2, "DINOv2 fixture directory required");
        const auto root = std::filesystem::u8path(argv[1]);
        const auto json = (root / "model.json").u8string();
        const auto encrypted = (root / "model.dvsenc").u8string();
        const auto input = cv::imread((root / "input.png").string(), cv::IMREAD_GRAYSCALE);
        const auto expected = cv::imread((root / "expected-mask.png").string(), cv::IMREAD_GRAYSCALE);
        require(!input.empty() && expected.size() == input.size(), "Missing fixture image/mask");
        VisionInference cpp;
        require(cpp.InitializeFromJson(json), "C++ DINOv2 load failed");
        const auto result = cpp.Segment(input);
        require(cv::norm(result.mask, expected, cv::NORM_INF) == 0, "C++ mask differs from Python ORT");
        require(result.num_classes == 3, "Class count lost");

        auto key = dvs_crypto::ReadKey(root / "model.key");
        dv_session *a = nullptr, *b = nullptr;
        require(dv_create_session(json.c_str(), nullptr, &a) == DV_STATUS_OK, dv_last_error(nullptr));
        std::unique_ptr<dv_session, decltype(&dv_close_session)> plain(a, dv_close_session);
        require(dv_create_session_encrypted(encrypted.c_str(), key.data(), key.size(), nullptr, &b) == DV_STATUS_OK,
                dv_last_error(nullptr));
        std::unique_ptr<dv_session, decltype(&dv_close_session)> secure(b, dv_close_session);
        dvs_crypto::Wipe(key.data(), key.size());
        // A non-contiguous BW8 ROI exercises the application's stride contract.
        cv::Mat padded(input.rows, input.cols + 13, CV_8UC1, cv::Scalar(0));
        auto roi = padded(cv::Rect(3, 0, input.cols, input.rows));
        input.copyTo(roi);
        dv_image_view view{sizeof(dv_image_view), DV_ABI_VERSION, roi.data, roi.cols, roi.rows,
                           roi.channels(), static_cast<int32_t>(roi.step)};
        for (auto session : {plain.get(), secure.get()}) {
            for (int repeat = 0; repeat != 3; ++repeat) {
                dv_result* raw = nullptr;
                require(dv_infer(session, &view, &raw) == DV_STATUS_OK, dv_last_error(session));
                std::unique_ptr<dv_result, decltype(&dv_release_result)> owner(raw, dv_release_result);
                require(raw && raw->kind == DV_RESULT_SEGMENTATION, "C ABI result kind mismatch");
                require(raw->mask && raw->mask_classes == 3, "Missing C ABI class mask");
                cv::Mat mask(raw->mask_height, raw->mask_width, CV_8UC1, raw->mask, raw->mask_stride_bytes);
                require(cv::norm(mask, expected, cv::NORM_INF) == 0, "C ABI plain/encrypted mask mismatch");
            }
        }
        std::cout << "PASS DINOv2: C++ and C ABI plain/encrypted BW8 masks match Python (3 repeats each)\n";
        return 0;
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        return 1;
    }
}
